#!/usr/bin/env python3
"""
Test models listed in a JSON file by sending the prompt:
  "Reply with exactly one word: OK"

Usage:
  python test_models.py models.json

The JSON file may be:
  - A list of model name strings: ["gpt-4", "gpt-3.5"]
  - A list of objects with a "model" key: [{"model":"gpt-4"}, {"model":"gpt-3.5"}]
  - An object with "models": [...] or "model": "gpt-4"

Requirements fulfilled:
  - Loads model list from JSON file passed as command-line argument
  - Sends the test prompt to each model with max_tokens=20
  - Attempts to include "temperature" but will retry without it if the model/API rejects it
  - Uses a 30-second timeout per request
  - Captures: model name, pass/fail, latency (seconds), response text (first 50 chars)
  - Prints results as a formatted table and a summary line
  - Uses only Python standard library (urllib, json, time, etc.)
"""

import sys
import json
import time
import urllib.request
import urllib.error
import socket
import os

API_URL = "http://127.0.0.1:4000/v1/chat/completions"
PROMPT = "Reply with exactly one word: OK"
MAX_TOKENS = 20
TIMEOUT = 30.0  # seconds
RESPONSE_PREVIEW_LEN = 50


def load_models_from_config(path):
    with open(path, "r", encoding="utf-8") as f:
        cfg = json.load(f)

    models = []

    def collect_from_list(lst):
        for item in lst:
            if isinstance(item, str):
                models.append(item)
            elif isinstance(item, dict) and "model" in item and isinstance(item["model"], str):
                models.append(item["model"])
            else:
                # ignore unknown entry types
                continue

    if isinstance(cfg, list):
        collect_from_list(cfg)
    elif isinstance(cfg, dict):
        if "models" in cfg and isinstance(cfg["models"], list):
            collect_from_list(cfg["models"])
        elif "model" in cfg and isinstance(cfg["model"], str):
            models.append(cfg["model"])
        else:
            # try interpreting dict values that are strings as model names
            for v in cfg.values():
                if isinstance(v, str):
                    models.append(v)
    else:
        raise ValueError("Unsupported JSON structure for models.")

    # Deduplicate while preserving order
    seen = set()
    filtered = []
    for m in models:
        if m not in seen:
            seen.add(m)
            filtered.append(m)
    return filtered


def build_payload(model_name, include_temperature=True):
    p = {
        "model": model_name,
        "messages": [{"role": "user", "content": PROMPT}],
        "max_tokens": MAX_TOKENS,
    }
    if include_temperature:
        # include temperature parameter (some models may reject it)
        p["temperature"] = 0.0
    return p


def extract_response_text(resp_body_text):
    # resp_body_text is a JSON string or plain text returned by the API
    try:
        parsed = json.loads(resp_body_text)
    except Exception:
        # not JSON, return raw truncated
        return resp_body_text.strip()

    # common OpenAI-compatible chat/completion shapes
    if isinstance(parsed, dict):
        # nested error shape? return message if present
        if "error" in parsed and isinstance(parsed["error"], dict):
            em = parsed["error"].get("message")
            if isinstance(em, str):
                return em.strip()

        choices = parsed.get("choices")
        if isinstance(choices, list) and len(choices) > 0:
            first = choices[0]
            # chat/completions: message.content
            msg = first.get("message")
            if isinstance(msg, dict):
                content = msg.get("content")
                if isinstance(content, str):
                    return content.strip()
            # older completions: text
            txt = first.get("text")
            if isinstance(txt, str):
                return txt.strip()

        # some compatibles return 'output' or other keys
        if "output" in parsed:
            out = parsed["output"]
            if isinstance(out, str):
                return out.strip()
            if isinstance(out, list) and out:
                if isinstance(out[0], str):
                    return out[0].strip()
    # fallback to the raw text
    return resp_body_text.strip()


def looks_like_temperature_unsupported(text):
    if not text:
        return False
    lower = text.lower()
    # Check for phrases commonly used when a parameter is not supported
    if "temperature" in lower and (
        "does not support" in lower
        or "not supported" in lower
        or "not support" in lower
        or "unsupported" in lower
        or "unknown parameter" in lower
        or "unexpected" in lower
        or "invalid parameter" in lower
    ):
        return True
    return False


def send_request(payload, timeout):
    data = json.dumps(payload).encode("utf-8")
    headers = {"Content-Type": "application/json"}
    api_key = os.environ.get("OPENAI_API_KEY") or os.environ.get("API_KEY") or os.environ.get("AUTHORIZATION")
    if api_key:
        # If an API key is present in env, include it as an Authorization header.
        # Many local dev servers accept no auth; this is optional.
        if not api_key.lower().startswith("bearer "):
            auth_val = "Bearer " + api_key
        else:
            auth_val = api_key
        headers["Authorization"] = auth_val

    req = urllib.request.Request(API_URL, data=data, headers=headers, method="POST")
    start = time.time()
    try:
        with urllib.request.urlopen(req, timeout=timeout) as resp:
            body = resp.read().decode("utf-8", errors="replace")
            latency = time.time() - start
            return True, latency, body
    except urllib.error.HTTPError as e:
        # read body from the error response (if any)
        try:
            body = e.read().decode("utf-8", errors="replace")
        except Exception:
            body = str(e)
        latency = time.time() - start
        return False, latency, body
    except (urllib.error.URLError, socket.timeout) as e:
        latency = time.time() - start
        return False, latency, str(e)
    except Exception as e:
        latency = time.time() - start
        return False, latency, str(e)


def test_model(model_name):
    # Try with temperature first, then retry without it if API rejects it.
    for include_temp in (True, False):
        payload = build_payload(model_name, include_temperature=include_temp)
        ok, latency, body = send_request(payload, TIMEOUT)
        response_text = extract_response_text(body)
        # If the HTTP call failed (ok==False) and message suggests temperature unsupported,
        # we should retry without temperature.
        if not ok and include_temp and looks_like_temperature_unsupported(body):
            # retry without temperature
            continue
        # Otherwise return the result (ok indicates request succeeded from HTTP perspective)
        # We'll treat 'ok' meaning HTTP-level success; the pass/fail of the test is based on content.
        # Pass if the model responded exactly "OK" (after strip).
        passed = False
        # If HTTPSuccess but response_text may still be an empty string; we still evaluate it.
        if ok:
            content = response_text.strip()
            # Accept exactly "OK"
            if content == "OK":
                passed = True
        else:
            # request-level failure -> treat as failed
            passed = False

        return {
            "model": model_name,
            "passed": passed,
            "latency": latency,
            "response": response_text,
            "http_ok": ok,
        }

    # If we exhausted retries (shouldn't normally happen), return failure
    return {
        "model": model_name,
        "passed": False,
        "latency": latency,
        "response": response_text,
        "http_ok": False,
    }


def format_latency(lat):
    try:
        return f"{lat:.3f}s"
    except Exception:
        return str(lat)


def trunc_preview(s, n):
    s = s.replace("\n", " ").strip()
    if len(s) <= n:
        return s
    return s[: n - 1] + "…"


def print_table(results):
    # Columns: Model, Status, Latency, Response
    model_col = "Model"
    status_col = "Status"
    latency_col = "Latency"
    resp_col = "Response"

    model_w = max(len(model_col), max((len(r["model"]) for r in results), default=0))
    status_w = len(status_col)
    latency_w = max(len(latency_col), 8)
    resp_w = max(len(resp_col), RESPONSE_PREVIEW_LEN)

    # Header
    hdr = f"{model_col:<{model_w}}  {status_col:<{status_w}}  {latency_col:>{latency_w}}  {resp_col}"
    print(hdr)
    print("-" * (len(hdr)))

    for r in results:
        model = r["model"]
        status = "✅" if r["passed"] else "❌"
        latency = format_latency(r["latency"])
        resp_preview = trunc_preview(r["response"], RESPONSE_PREVIEW_LEN)
        print(f"{model:<{model_w}}  {status:<{status_w}}  {latency:>{latency_w}}  {resp_preview}")

    # Summary
    total = len(results)
    ok_count = sum(1 for r in results if r["passed"])
    fail_count = total - ok_count
    print()
    print(f"Total: {total} models | ✅ {ok_count} working | ❌ {fail_count} failed")


def main():
    if len(sys.argv) != 2:
        print("Usage: python test_models.py models.json")
        sys.exit(2)
    cfg_path = sys.argv[1]
    try:
        models = load_models_from_config(cfg_path)
    except Exception as e:
        print("Failed to load model list from config:", e)
        sys.exit(1)

    if not models:
        print("No models found in config.")
        sys.exit(1)

    results = []
    for m in models:
        print(f"Testing model: {m} ...", end="", flush=True)
        res = test_model(m)
        results.append(res)
        status = "OK" if res["passed"] else "FAIL"
        print(" " + status)

    print()
    print_table(results)


if __name__ == "__main__":
    main()
